package com.revivex.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant;
@Entity @Table(name="payment_events")
public class PaymentEvent { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String customer; private String merchant; private BigDecimal amount; private String currency; private String eventType; private String failureCode; private String channel; private int previousAttempts; private int previousContacts; private double historicalSuccessRate; private boolean highRisk; private boolean recovered; private Instant occurredAt;
 public PaymentEvent(){} public PaymentEvent(String customer,String merchant,BigDecimal amount,String eventType,String failureCode,String channel,int attempts,int contacts,double success,boolean risk){this.customer=customer;this.merchant=merchant;this.amount=amount;this.currency="INR";this.eventType=eventType;this.failureCode=failureCode;this.channel=channel;this.previousAttempts=attempts;this.previousContacts=contacts;this.historicalSuccessRate=success;this.highRisk=risk;this.occurredAt=Instant.now();}
 @PrePersist void init(){if(occurredAt==null)occurredAt=Instant.now();} public Long getId(){return id;} public String getCustomer(){return customer;} public String getMerchant(){return merchant;} public BigDecimal getAmount(){return amount;} public String getCurrency(){return currency;} public String getEventType(){return eventType;} public String getFailureCode(){return failureCode;} public String getChannel(){return channel;} public int getPreviousAttempts(){return previousAttempts;} public int getPreviousContacts(){return previousContacts;} public double getHistoricalSuccessRate(){return historicalSuccessRate;} public boolean isHighRisk(){return highRisk;} public boolean isRecovered(){return recovered;} public void setRecovered(boolean v){recovered=v;} public Instant getOccurredAt(){return occurredAt;} }
